// Leaderboard. Times are epoch milliseconds.

/** Whoever ranks: an anonymous browser's player, or an account (every browser signed in to it). */
export const boardProfile = sqliteTable(
  'board_profile',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .unique()
      .references(() => user.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    /** The name without case (names.ts nameKey): name + tag is unique on it. Null with `tag` on a row no tag was given yet. */
    nameKey: text('name_key'),
    /** The number after the name (Name#1234). A rename keeps it unless the new name already has it. */
    tag: integer('tag'),
    /** A character id: that character's portrait. */
    avatarHero: text('avatar_hero'),
    /** A board_avatar id: an uploaded picture (wins over avatarHero). */
    avatarImage: text('avatar_image'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull()
  },
  (t) => [uniqueIndex('board_profile_name_tag_uq').on(t.nameKey, t.tag)]
);

/** A browser's anonymous id. It is the browser's only credential, so no response ever contains it. */
export const boardPlayer = sqliteTable(
  'board_player',
  {
    id: text('id').primaryKey(),
    profileId: text('profile_id')
      .notNull()
      .references(() => boardProfile.id, { onDelete: 'cascade' }),
    createdAt: integer('created_at').notNull(),
    lastSeenAt: integer('last_seen_at').notNull()
  },
  (t) => [index('board_player_profile_idx').on(t.profileId)]
);

/** One finished match of one player, as the client reported it. */
export const boardMatch = sqliteTable(
  'board_match',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    playerId: text('player_id')
      .notNull()
      .references(() => boardPlayer.id, { onDelete: 'cascade' }),
    /** Copied from the player so ranking needs no join; moved when players merge into an account. */
    profileId: text('profile_id')
      .notNull()
      .references(() => boardProfile.id, { onDelete: 'cascade' }),
    /** The client's id for the match: a retried upload lands on the same row. */
    matchKey: text('match_key').notNull(),
    mode: text('mode', { enum: ['solo', 'ffa', 'tdm'] }).notNull(),
    map: text('map').notNull(),
    difficulty: text('difficulty', { enum: ['easy', 'normal', 'hard'] }),
    wave: integer('wave').notNull(),
    character: text('character').notNull(),
    endedAt: integer('ended_at').notNull(),
    durationS: integer('duration_s').notNull(),
    score: integer('score').notNull(),
    kills: integer('kills').notNull(),
    deaths: integer('deaths').notNull(),
    assists: integer('assists').notNull(),
    headshots: integer('headshots').notNull(),
    /** Place by score among everyone in the match (1 = top). */
    placement: integer('placement').notNull(),
    players: integer('players').notNull(),
    result: text('result', { enum: ['win', 'loss', 'draw'] }),
    /** JSON (contract.ts MatchDetail): the score panel the player saw at the end. Null on matches stored before it was kept. */
    detail: text('detail'),
    /** JSON (lib/achievements/tally.ts MatchTally): what the match adds to its player's achievement totals. Null on matches stored before achievements until they are counted. */
    tally: text('tally'),
    /** 1 once the tally is in board_stat (lib/achievements/store.ts settle). */
    counted: integer('counted').notNull().default(0),
    createdAt: integer('created_at').notNull()
  },
  (t) => [
    uniqueIndex('board_match_player_key_uq').on(t.playerId, t.matchKey),
    index('board_match_board_idx').on(t.mode, t.difficulty, t.map),
    index('board_match_profile_idx').on(t.profileId, t.endedAt),
    index('board_match_uncounted_idx')
      .on(t.profileId)
      .where(sql`${t.counted} = 0`)
  ]
);

/** Uploaded avatars, small WebP/JPEG/PNG squares kept as base64. */
export const boardAvatar = sqliteTable(
  'board_avatar',
  {
    id: text('id').primaryKey(),
    profileId: text('profile_id')
      .notNull()
      .references(() => boardProfile.id, { onDelete: 'cascade' }),
    mime: text('mime').notNull(),
    data: text('data').notNull(),
    createdAt: integer('created_at').notNull()
  },
  (t) => [index('board_avatar_profile_idx').on(t.profileId)]
);

/** Fixed-window request counters for rate limits. */
export const boardRate = sqliteTable(
  'board_rate',
  {
    key: text('key').notNull(),
    window: integer('window').notNull(),
    count: integer('count').notNull()
  },
  (t) => [primaryKey({ columns: [t.key, t.window] })]
);

/** Achievement totals of one browser's player (lib/achievements/catalogue.ts StatKey); a profile's are the sum over its players. */
export const boardStat = sqliteTable(
  'board_stat',
  {
    playerId: text('player_id')
      .notNull()
      .references(() => boardPlayer.id, { onDelete: 'cascade' }),
    stat: text('stat').notNull(),
    value: integer('value').notNull()
  },
  (t) => [primaryKey({ columns: [t.playerId, t.stat] })]
);

/** An achievement tier a profile reached, and when. */
export const boardUnlock = sqliteTable(
  'board_unlock',
  {
    profileId: text('profile_id')
      .notNull()
      .references(() => boardProfile.id, { onDelete: 'cascade' }),
    achievement: text('achievement').notNull(),
    /** From 1: the achievement's first goal. */
    tier: integer('tier').notNull(),
    unlockedAt: integer('unlocked_at').notNull()
  },
  (t) => [primaryKey({ columns: [t.profileId, t.achievement, t.tier] })]
);
